  1	/**
  2	 * The profiles the plugin ships: a deck laid out before anybody touches it.
  3	 *
  4	 * Forty-four `.streamDeckProfile` files, eleven layouts across four decks.
  5	 * One is generic - the keys any run wants, whatever pack it is playing -
  6	 * and the rest are written against a pack, with its moves on keys, its
  7	 * counters and resources on the numbers, and the setups for its tool ready
  8	 * to hand out. Nothing is typed in here: the ids come out of the pack files
  9	 * through the same loader the app and the CLI use, so a renamed move
 10	 * changes the profile on the next run of this script rather than going
 11	 * quietly dead on somebody's deck.
 12	 *
 13	 * `npm run profiles -w streamdeck`. It also writes `src/profiles.ts`, which
 14	 * is the one thing here the plugin reads at run time: the table that turns a
 15	 * run's pack into the profile to switch a deck to.
 16	 *
 17	 * The container is a zip whose single top-level entry is a
 18	 * `<UUID>.sdProfile/` folder. That is not documented anywhere; it is what
 19	 * the Stream Deck app's own `DefaultProfiles` and the profiles bundled with
 20	 * Elgato's Volume Controller plugin turn out to be, and the writer below
 21	 * matches them entry for entry.
 22	 */
 23	import { createHash } from "node:crypto";
 24	import { mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
 25	import { basename, dirname, join } from "node:path";
 26	import { fileURLToPath } from "node:url";
 27	
 28	import { loadPackText, loadSetupText } from "@runlog/rules-schema";
 29	
 30	import { BASE, DEMO, DEVICES, DIALS, isWarp, SKETCHES, SLUGS } from "./layouts.mjs";
 31	
 32	const here = dirname(fileURLToPath(import.meta.url));
 33	const plugin = join(here, "..", "com.scrthq.runlog.sdPlugin");
 34	const repo = join(here, "..", "..");
 35	
 36	/** Our own manifest, so an action's `Name` and the plugin version are never retyped. */
 37	const MANIFEST = JSON.parse(readFileSync(join(plugin, "manifest.json"), "utf8"));
 38	
 39	/** The action `Name` the app expects beside each of our UUIDs. */
 40	const NAMES = Object.fromEntries(MANIFEST.Actions.map((a) => [a.UUID, a.Name]));
 41	
 42	/** The plugin block every one of our actions carries. */
 43	const PLUGIN = { Name: MANIFEST.Name, UUID: MANIFEST.UUID, Version: MANIFEST.Version };
 44	
 45	/** What a key face looks like before the plugin draws over it. */
 46	const STATE = {
 47	  FontFamily: "",
 48	  FontSize: 12,
 49	  FontStyle: "",
 50	  FontUnderline: false,
 51	  OutlineThickness: 2,
 52	  ShowTitle: true,
 53	  TitleAlignment: "top",
 54	  TitleColor: "#ffffff",
 55	};
 56	
 57	/** The app's own page turns, which are not ours and take none of our furniture. */
 58	const PAGE_PLUGIN = { Name: "Pages", UUID: "com.elgato.streamdeck.page", Version: "1.0" };
 59	const TURNS = {
 60	  next: { Name: "Next Page", UUID: "com.elgato.streamdeck.page.next" },
 61	  previous: { Name: "Previous Page", UUID: "com.elgato.streamdeck.page.previous" },
 62	};
 63	
 64	/**
 65	 * Stable ids, so regenerating a profile is not a diff.
 66	 *
 67	 * A profile folder, its pages and every action on them want a UUID, and the
 68	 * app does not care where they came from as long as they are unique. Random
 69	 * ones would rewrite all twelve files on every run and bury a real change in
 70	 * the churn, so each is derived from what it is - the same name in, the same
 71	 * UUID out. Version 5 in shape, off a namespace of our own.
 72	 */
 73	const NAMESPACE = createHash("sha1").update("com.scrthq.runlog.profiles").digest().subarray(0, 16);
 74	
 75	export function stableId(name) {
 76	  const h = createHash("sha1").update(NAMESPACE).update(name, "utf8").digest();
 77	  h[6] = (h[6] & 0x0f) | 0x50;
 78	  h[8] = (h[8] & 0x3f) | 0x80;
 79	  const s = h.subarray(0, 16).toString("hex");
 80	  return `${s.slice(0, 8)}-${s.slice(8, 12)}-${s.slice(12, 16)}-${s.slice(16, 20)}-${s.slice(20, 32)}`;
 81	}
 82	
 83	/**
 84	 * One key, as the app stores it.
 85	 *
 86	 * `LinkedTitle` true is what lets the plugin's own title survive a copy of
 87	 * the key to another slot, and `State: 0` with a single `States` entry is
 88	 * every one of our actions: none of them has a second state.
 89	 */
 90	function entry(id, spec) {
 91	  const uuid = `${MANIFEST.UUID}.${spec.action}`;
 92	  return {
 93	    ActionID: id,
 94	    LinkedTitle: true,
 95	    Name: NAMES[uuid],
 96	    Plugin: PLUGIN,
 97	    Resources: null,
 98	    Settings: spec.settings ?? {},
 99	    State: 0,
100	    States: [STATE],
101	    UUID: uuid,
102	  };
103	}
104	
105	/** A page turn, which carries the app's plugin block and an empty face. */
106	function turn(id, which) {
107	  return {
108	    ActionID: id,
109	    LinkedTitle: true,
110	    Name: TURNS[which].Name,
111	    Plugin: PAGE_PLUGIN,
112	    Resources: null,
113	    Settings: {},
114	    State: 0,
115	    States: [{}],
116	    UUID: TURNS[which].UUID,
117	  };
118	}
119	
120	/**
121	 * The keys a pack adds to the generic fourteen.
122	 *
123	 * Its moves first, because those are what somebody presses; then the
124	 * numbers it keeps; then the setups for whatever tool it is driven by.
125	 *
126	 * A hidden counter is left out. `packages/engine/src/snapshot.ts` does not
127	 * publish one, so a key set to it would say nothing for ever - and hidden
128	 * is the pack saying it is bookkeeping rather than a number to watch.
129	 *
130	 * The setups are the tool's, not the pack's: a setup names a tool and no
131	 * pack at all, which is `forTool` in `apps/web/src/control/setups.ts`, and
132	 * they are ordered by title the way the app's own picker orders them. A
133	 * pack with no shipped control profile names no tool and gets none.
134	 *
135	 * A setup `isWarp` gets a Command key instead of an Apply-setup one: its
136	 * operations go to the tool once, and the run's own setup is untouched.
137	 *
138	 * Last, a key that opens the pack's rules in the browser: a pack profile
139	 * is the one place that key has a pack to open.
140	 */
141	export function packKeys(pack, setups) {
142	  const keys = [];
143	  for (const id of Object.keys(pack.moves ?? {})) keys.push({ action: "press", settings: { target: { kind: "move", id } } });
144	  for (const [id, counter] of Object.entries(pack.counters ?? {})) {
145	    if (!counter.hidden) keys.push({ action: "metric", settings: { field: { counter: id } } });
146	  }
147	  for (const id of Object.keys(pack.resources ?? {})) keys.push({ action: "metric", settings: { field: { resource: id } } });
148	  for (const setup of setups) {
149	    keys.push(
150	      isWarp(setup)
151	        ? { action: "command", settings: { command: { id: setup.id, title: setup.title } } }
152	        : { action: "setup", settings: { setup: { id: setup.id, title: setup.title } } },
153	    );
154	  }
155	  keys.push({ action: "open", settings: { target: "rules" } });
156	  return keys;
157	}
158	
159	/**
160	 * The keys cut into pages, with room kept for the turns.
161	 *
162	 * Every page after the first spends its first position on a way back, and
163	 * every page with more behind it spends its last on a way on. The last page
164	 * spends neither, so a layout that fits exactly does not grow a turn key
165	 * pointing at nothing.
166	 */
167	export function paginate(keys, capacity) {
168	  const pages = [];
169	  let i = 0;
170	  while (i < keys.length) {
171	    const back = pages.length > 0 ? 1 : 0;
172	    let room = capacity - back;
173	    const more = keys.length - i > room;
174	    if (more) room -= 1;
175	    pages.push({ back: back === 1, more, keys: keys.slice(i, i + room) });
176	    i += room;
177	  }
178	  return pages;
179	}
180	
181	/** Row-major: the app names a position column first, and the top-left one is `0,0`. */
182	const at = (slot, columns) => `${slot % columns},${Math.floor(slot / columns)}`;
183	
184	/**
185	 * One profile, as a set of files, before anything is zipped.
186	 *
187	 * `ids` is handed in so a test can run the whole thing on a counter and
188	 * compare what came out; the default derives them from the profile's own
189	 * name and is what the committed files are built with.
190	 */
191	export function profile({ slug, device, name, keys }, ids = stableId) {
192	  const { model, columns, rows, dials } = DEVICES[device];
193	  const capacity = columns * rows;
194	  const cut = paginate(keys, capacity);
195	
196	  const files = {};
197	  const pageIds = [];
198	  for (const [index, page] of cut.entries()) {
199	    const id = ids(`${slug}/${device}/page/${index}`).toUpperCase();
200	    pageIds.push(id);
201	
202	    const actions = {};
203	    if (page.back) actions[at(0, columns)] = turn(ids(`${slug}/${device}/page/${index}/back`), "previous");
204	    for (const [n, key] of page.keys.entries()) {
205	      const slot = (page.back ? 1 : 0) + n;
206	      actions[at(slot, columns)] = entry(ids(`${slug}/${device}/page/${index}/key/${n}`), key);
207	    }
208	    if (page.more) actions[at(capacity - 1, columns)] = turn(ids(`${slug}/${device}/page/${index}/more`), "next");
209	
210	    const controllers = [{ Type: "Keypad", Actions: actions }];
211	    if (dials > 0) {
212	      const wheel = {};
213	      for (const [n, dial] of DIALS.slice(0, dials).entries()) {
214	        wheel[`${n},0`] = entry(ids(`${slug}/${device}/page/${index}/dial/${n}`), dial);
215	      }
216	      controllers.push({ Type: "Encoder", Actions: wheel });
217	    }
218	    files[`Profiles/${id}/manifest.json`] = { Controllers: controllers, Icon: "", Name: "" };
219	  }
220	
221	  // The default page is the empty one the app falls back to. It is not in
222	  // `Pages`, which is why a profile with one page still lists two folders.
223	  const empty = ids(`${slug}/${device}/default`).toUpperCase();
224	  files[`Profiles/${empty}/manifest.json`] = { Controllers: [{ Actions: null, Type: "Keypad" }], Icon: "", Name: "" };
225	
226	  files["manifest.json"] = {
227	    // Empty, and it has to be: the serial that sits here in a profile the
228	    // app wrote is one particular deck on one particular desk, and a
229	    // profile we ship goes to everybody's.
230	    Device: { Model: model, UUID: "" },
231	    Name: name,
232	    Pages: {
233	      Current: pageIds[0].toLowerCase(),
234	      Default: empty.toLowerCase(),
235	      Pages: pageIds.map((id) => id.toLowerCase()),
236	    },
237	    Version: "3.0",
238	  };
239	
240	  return { folder: `${ids(`${slug}/${device}`).toUpperCase()}.sdProfile`, files };
241	}
242	
243	/* -------------------------------------------------------------------- */
244	/* The container                                                         */
245	/* -------------------------------------------------------------------- */
246	
247	const CRC = (() => {
248	  const table = new Int32Array(256);
249	  for (let n = 0; n < 256; n++) {
250	    let c = n;
251	    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
252	    table[n] = c;
253	  }
254	  return table;
255	})();
256	
257	function crc32(buf) {
258	  let c = ~0;
259	  for (const b of buf) c = CRC[(c ^ b) & 0xff] ^ (c >>> 8);
260	  return ~c >>> 0;
261	}
262	
263	/**
264	 * A stored-only zip, written here rather than pulled in.
265	 *
266	 * Nothing in the repository zips anything else, and the alternative is a
267	 * dependency for two hundred lines of header. Stored rather than deflated
268	 * because a profile is a few kilobytes of JSON and the app reads either;
269	 * every timestamp is the same fixed one, so running this twice produces the
270	 * same bytes twice and the committed files only move when a layout does.
271	 */
272	export function zip(entries) {
273	  const DOS_DATE = 33; // 1980-01-01, the earliest a zip can say.
274	  const local = [];
275	  const central = [];
276	  let offset = 0;
277	  for (const { name, data } of entries) {
278	    const label = Buffer.from(name, "utf8");
279	    const body = data ?? Buffer.alloc(0);
280	    const sum = crc32(body);
281	
282	    const head = Buffer.alloc(30);
283	    head.writeUInt32LE(0x04034b50, 0);
284	    head.writeUInt16LE(20, 4);
285	    head.writeUInt16LE(0, 6);
286	    head.writeUInt16LE(0, 8);
287	    head.writeUInt16LE(0, 10);
288	    head.writeUInt16LE(DOS_DATE, 12);
289	    head.writeUInt32LE(sum, 14);
290	    head.writeUInt32LE(body.length, 18);
291	    head.writeUInt32LE(body.length, 22);
292	    head.writeUInt16LE(label.length, 26);
293	    head.writeUInt16LE(0, 28);
294	    local.push(head, label, body);
295	
296	    const listed = Buffer.alloc(46);
297	    listed.writeUInt32LE(0x02014b50, 0);
298	    listed.writeUInt16LE(20, 4);
299	    listed.writeUInt16LE(20, 6);
300	    listed.writeUInt16LE(0, 8);
301	    listed.writeUInt16LE(0, 10);
302	    listed.writeUInt16LE(0, 12);
303	    listed.writeUInt16LE(DOS_DATE, 14);
304	    listed.writeUInt32LE(sum, 16);
305	    listed.writeUInt32LE(body.length, 20);
306	    listed.writeUInt32LE(body.length, 24);
307	    listed.writeUInt16LE(label.length, 28);
308	    listed.writeUInt16LE(0, 30);
309	    listed.writeUInt16LE(0, 32);
310	    listed.writeUInt16LE(0, 34);
311	    listed.writeUInt16LE(0, 36);
312	    // The directory bit, so an unpacker makes the folder rather than a file.
313	    listed.writeUInt32LE(name.endsWith("/") ? 0x10 : 0, 38);
314	    listed.writeUInt32LE(offset, 42);
315	    central.push(listed, label);
316	
317	    offset += head.length + label.length + body.length;
318	  }
319	
320	  const directory = Buffer.concat(central);
321	  const end = Buffer.alloc(22);
322	  end.writeUInt32LE(0x06054b50, 0);
323	  end.writeUInt16LE(entries.length, 8);
324	  end.writeUInt16LE(entries.length, 10);
325	  end.writeUInt32LE(directory.length, 12);
326	  end.writeUInt32LE(offset, 16);
327	  return Buffer.concat([...local, directory, end]);
328	}
329	
330	/** A built profile as the bytes of a `.streamDeckProfile`, folders and all. */
331	export function container({ folder, files }) {
332	  const entries = [{ name: `${folder}/` }];
333	  const folders = new Set();
334	  for (const path of Object.keys(files)) {
335	    const parts = path.split("/").slice(0, -1);
336	    for (let i = 1; i <= parts.length; i++) folders.add(parts.slice(0, i).join("/"));
337	  }
338	  for (const dir of [...folders].sort()) entries.push({ name: `${folder}/${dir}/` });
339	  for (const [path, body] of Object.entries(files)) {
340	    entries.push({ name: `${folder}/${path}`, data: Buffer.from(JSON.stringify(body), "utf8") });
341	  }
342	  return zip(entries);
343	}
344	
345	/* -------------------------------------------------------------------- */
346	/* What goes in them                                                     */
347	/* -------------------------------------------------------------------- */
348	
349	/** The tool a pack is driven by, from the shipped control profile written for it. */
350	function toolFor(packId) {
351	  const dir = join(repo, "packs", "profiles");
352	  for (const file of readdirSync(dir).filter((f) => f.endsWith(".json"))) {
353	    // Read as JSON rather than through the app's reader: that one wants the
354	    // tool's operation catalog to say anything useful, and all this needs is
355	    // two fields that `apps/web/src/control/shipped.test.ts` already holds
356	    // every one of these files to.
357	    const profile = JSON.parse(readFileSync(join(dir, file), "utf8"));
358	    if (profile.pack === packId) return profile.tool;
359	  }
360	  return undefined;
361	}
362	
363	/** Every setup written for a tool, by title, the way the app's picker lists them. */
364	function setupsFor(tool) {
365	  if (!tool) return [];
366	  const dir = join(repo, "packs", "setups");
367	  const out = [];
368	  for (const file of readdirSync(dir).filter((f) => f.endsWith(".yaml"))) {
369	    const parsed = loadSetupText(readFileSync(join(dir, file), "utf8"), "yaml");
370	    if (parsed.ok && parsed.setup.tool.toLowerCase() === tool.toLowerCase()) out.push(parsed.setup);
371	  }
372	  return out.sort((a, b) => a.title.localeCompare(b.title));
373	}
374	
375	/**
376	 * The layouts, in the order the manifest lists them: generic, demo, sketches.
377	 *
378	 * Every pack that ships gets one. Forty profiles auto-installing on a deck
379	 * would be forty entries in somebody's profile list on the day they install
380	 * the plugin, so a pack's four wait in the package and the plugin asks for
381	 * the one it needs; `main` writes the table it asks through.
382	 *
383	 * A sketch that no longer parses is left out rather than throwing. It is a
384	 * file in the repository with its own tests, and a broken one should fail
385	 * there rather than stop every other profile being written.
386	 */
387	export function layouts() {
388	  const sketches = readdirSync(join(repo, SKETCHES))
389	    .filter((f) => f.endsWith(".yaml"))
390	    .sort()
391	    .map((f) => ({ slug: SLUGS[basename(f, ".yaml")] ?? basename(f, ".yaml"), file: `${SKETCHES}/${f}` }));
392	
393	  const out = [{ slug: "runlog", name: "Runlog", pack: null }];
394	  for (const { slug, file } of [DEMO, ...sketches]) {
395	    const parsed = loadPackText(readFileSync(join(repo, file), "utf8"), "yaml");
396	    if (!parsed.ok) continue;
397	    // The pack's own title, and nothing else: the Stream Deck app already
398	    // says which plugin a profile came with.
399	    out.push({ slug, name: parsed.pack.title, pack: parsed.pack });
400	  }
401	  return out;
402	}
403	
404	/** The forty-four profiles, named and keyed, ready to be laid out on a grid. */
405	export function specs() {
406	  const out = [];
407	  for (const layout of layouts()) {
408	    const keys = layout.pack ? [...BASE, ...packKeys(layout.pack, setupsFor(toolFor(layout.pack.id)))] : BASE;
409	    for (const device of Object.keys(DEVICES)) out.push({ slug: layout.slug, device, name: layout.name, keys });
410	  }
411	  return out;
412	}
413	
414	/**
415	 * The table the plugin switches through, as a module it can import.
416	 *
417	 * The plugin never spells a profile name out. A pack renamed here, or a
418	 * sketch added to the repository, moves this file on the next run of the
419	 * generator, and the two stay one thing rather than two lists that drift.
420	 */
421	export function table(list = layouts()) {
422	  const packs = list.filter((l) => l.pack).map((l) => `  "${l.pack.id}": "${l.slug}",`);
423	  const decks = Object.entries(DEVICES).map(([device, { type }]) => `  ${type}: "${device}",`);
424	  return `/**
425	 * Which profile a run's pack is laid out in, and what each deck is called.
426	 *
427	 * Written by \`design/profiles.mjs\`: run \`npm run profiles -w streamdeck\`
428	 * and commit what moves. Editing it by hand renames a profile the plugin
429	 * asks for without renaming the file behind it, and the switch then does
430	 * nothing at all.
431	 */
432	
433	/** The slug of the profile laid out for each pack the plugin ships. */
434	export const PACK_PROFILES: Record<string, string> = {
435	${packs.join("\n")}
436	};
437	
438	/** What a profile name calls each deck, by the SDK's \`DeviceType\`. */
439	export const DEVICE_PROFILES: Record<number, string> = {
440	${decks.join("\n")}
441	};
442	
443	/** The layout a run gets where its pack ships none, which is every Marketplace pack. */
444	export const GENERIC_PROFILE = "runlog";
445	
446	/**
447	 * The profile to put a deck on for a run of this pack.
448	 *
449	 * \`null\` for a deck nothing here is laid out for - a Pedal, a Neo - which is
450	 * a deck to leave alone rather than one to push the generic layout onto.
451	 */
452	export function profileFor(packId: string | undefined, device: number): string | null {
453	  const deck = DEVICE_PROFILES[device];
454	  if (deck === undefined) return null;
455	  const slug = (packId === undefined ? undefined : PACK_PROFILES[packId]) ?? GENERIC_PROFILE;
456	  return \`profiles/\${slug}-\${deck}\`;
457	}
458	`;
459	}
460	
461	function main() {
462	  const dir = join(plugin, "profiles");
463	  mkdirSync(dir, { recursive: true });
464	
465	  const written = [];
466	  for (const spec of specs()) {
467	    const file = `${spec.slug}-${spec.device}`;
468	    writeFileSync(join(dir, `${file}.streamDeckProfile`), container(profile(spec)));
469	    // The generic four come with the plugin; a pack's four are installed the
470	    // first time a deck follows a run of that pack.
471	    written.push({ name: `profiles/${file}`, type: DEVICES[spec.device].type, auto: spec.slug === "runlog" });
472	  }
473	
474	  writeFileSync(join(here, "..", "src", "profiles.ts"), table());
475	
476	  // The manifest is edited by hand - a generator that rewrites it fights the
477	  // formatter over every other line - so the one thing checked here is that
478	  // it still lists what was just written, in the same order.
479	  const listed = (MANIFEST.Profiles ?? []).map((p) => `${p.Name}:${p.DeviceType}:${p.AutoInstall}`).join(" ");
480	  const expected = written.map((p) => `${p.name}:${p.type}:${p.auto}`).join(" ");
481	  if (listed !== expected) throw new Error(`manifest.json lists\n  ${listed}\nbut this wrote\n  ${expected}`);
482	
483	  console.log(`${written.length} profiles written to ${dir}`);
484	}
485	
486	if (process.argv[1] === fileURLToPath(import.meta.url)) main();

