 87	 * the key to another slot, and `State: 0` with a single `States` entry is
 88	 * every one of our actions: none of them has a second state.
 89	 */
 90	function entry(id, spec) {
 91	  const uuid = `${MANIFEST.UUID}.${spec.action}`;
 92	  return {
 93	    ActionID: id,
 94	    LinkedTitle: true,
 95	    Name: NAMES[uuid],
 96	    Plugin: PLUGIN,
 97	    Resources: null,
 98	    Settings: spec.settings ?? {},
 99	    State: 0,
100	    States: [STATE],
101	    UUID: uuid,
102	  };
103	}
104	
105	/** A page turn, which carries the app's plugin block and an empty face. */
106	function turn(id, which) {
107	  return {
108	    ActionID: id,
109	    LinkedTitle: true,
110	    Name: TURNS[which].Name,
111	    Plugin: PAGE_PLUGIN,
112	    Resources: null,
113	    Settings: {},
114	    State: 0,
115	    States: [{}],
116	    UUID: TURNS[which].UUID,
117	  };
118	}
