227	      expect(pack.ok).toBe(true);
228	    });
229	
230	    for (const device of Object.keys(DEVICES)) {
231	      it(`carries exactly the pack's moves, counters, resources and setups on a ${device}`, () => {
232	        const built = all.find(({ spec }) => spec.slug === "elden-ring" && spec.device === device).built;
233	        const settings = placed(built).map((p) => p.action.Settings);
234	
235	        const moves = settings.filter((s) => s.target?.kind === "move").map((s) => s.target.id);
236	        expect(moves.sort()).toEqual(Object.keys(pack.pack.moves).sort());
237	
238	        const counters = settings.filter((s) => typeof s.field === "object" && "counter" in s.field).map((s) => s.field.counter);
239	        const shown = Object.entries(pack.pack.counters)
240	          .filter(([, c]) => !c.hidden)
241	          .map(([id]) => id);
242	        expect(counters.sort()).toEqual(shown.sort());
243	
244	        const resources = settings.filter((s) => typeof s.field === "object" && "resource" in s.field).map((s) => s.field.resource);
245	        expect(resources.sort()).toEqual(Object.keys(pack.pack.resources).sort());
246	
247	        const chosenSetups = settings.filter((s) => s.setup).map((s) => s.setup.id);
248	        const chosenCommands = settings.filter((s) => s.command).map((s) => s.command.id);
249	        expect([...chosenSetups, ...chosenCommands].sort()).toEqual(shippedFor(tool).sort());
250	        // The loadouts, at least, and by id rather than by count: a setup
251	        // that stopped naming this tool would otherwise vanish unremarked.
252	        for (const id of setups) expect(chosenSetups).toContain(`com.scrthq.runlog.setups.${id}`);
253	        // Start of the DLC warps the player, so it is a Command key rather
254	        // than an Apply-setup one.
255	        expect(chosenCommands).toEqual(["com.scrthq.runlog.setups.start-of-the-dlc"]);
256	      });
257	    }
258	  });
259	
260	  it("gives every profile the run and the guide, and only a pack's the rules", () => {
261	    for (const { spec, built } of all) {
262	      const targets = placed(built)
263	        .filter((p) => p.action.UUID === "com.scrthq.runlog.open")
264	        .map((p) => p.action.Settings.target)
265	        .sort();
266	      const want = spec.slug === "runlog" ? ["guide", "run"] : ["guide", "rules", "run"];
267	      expect(targets, `${spec.slug}-${spec.device}`).toEqual(want);
268	    }
269	  });
270	
271	  it("gives the demo pack no setup keys, because it names no tool", () => {
272	    const built = all.find(({ spec }) => spec.slug === "demo" && spec.device === "xl").built;
273	    expect(placed(built).filter((p) => p.action.UUID === "com.scrthq.runlog.setup")).toHaveLength(0);
274	  });
275	});
276	
277	/** Every shipped setup written for a tool, by id. */
278	function shippedFor(tool) {
279	  const dir = join(repo, "packs", "setups");
280	  return readdirSync(dir)
281	    .filter((f) => f.endsWith(".yaml"))
282	    .map((f) => loadSetupText(readFileSync(join(dir, f), "utf8"), "yaml"))
283	    .filter((r) => r.ok && r.setup.tool.toLowerCase() === tool.toLowerCase())
284	    .map((r) => r.setup.id);
285	}

