  1	import { useEffect, useMemo, useState } from "react";
  2	import { loadPackText, type Pack } from "@runlog/rules-schema";
  3	import { useDocDrawer } from "../docs/DocDrawer.tsx";
  4	import {
  5	  facets,
  6	  FEATURES,
  7	  filterMarketplace,
  8	  kindCounts,
  9	  loadMarketplace,
 10	  publishersOf,
 11	  type MarketplaceEntry,
 12	  type Feature,
 13	} from "./marketplace.ts";
 14	import type { ListingKind } from "@runlog/rules-schema";
 15	import { useHosted } from "../hosted/HostedProvider.tsx";
 16	
 17	/**
 18	 * The marketplace, laid out as a market: cards in a grid, a sidebar to narrow
 19	 * them. Everything here is free and comes with the app for now; the shape
 20	 * is the one a marketplace with publishers and prices will fill in.
 21	 *
 22	 * What the sidebar filters on comes from the packs themselves: a category
 23	 * and tags the author wrote, and features read off the modes, solo,
 24	 * together, moderated, seeded, so "show me something we can all play"
 25	 * is a checkbox and not a search for the right word.
 26	 *
 27	 * "Docs" opens the pack's paper in the side drawer, on the summary: the
 28	 * shape of the game, its tables by name, its modes, what you need, and
 29	 * never its rules. It is what a listing shows before anyone has the pack;
 30	 * the other documents are the drawer's tabs, where the pack's text may be
 31	 * read. A priced listing carries only its summary, so that is the one tab.
 32	 */
 33	export function MarketplaceView({
 34	  focus = null,
 35	  mine,
 36	  bought = new Set(),
 37	  onAdd,
 38	  onBuy,
 39	  onFetch,
 40	  onOpen,
 41	  onBack,
 42	}: {
 43	  /** A pack to open the About of on arrival, from a deep link. */
 44	  focus?: string | null;
 45	  /** Ids of the packs already in the library. */
 46	  mine: ReadonlySet<string>;
 47	  /** Ids of the packs the account has bought, on the shelf here or not. */
 48	  bought?: ReadonlySet<string>;
 49	  onAdd: (entry: MarketplaceEntry) => Promise<void>;
 50	  /** Buy a priced listing; absent where nobody is signed in. */
 51	  onBuy?: (entry: MarketplaceEntry) => Promise<void>;
 52	  /** Bring a bought copy onto this device. */
 53	  onFetch?: (entry: MarketplaceEntry) => Promise<void>;
 54	  onOpen: (id: string) => void;
 55	  onBack: () => void;
 56	}) {
 57	  const [entries, setEntries] = useState<MarketplaceEntry[] | null>(null);
 58	  const [busy, setBusy] = useState<string | null>(null);
 59	  const drawer = useDocDrawer();
 60	  /** The pack whose paper is being read for the drawer, while it is. */
 61	  const [reading, setReading] = useState<string | null>(null);
 62	  const [q, setQ] = useState("");
 63	  const [categories, setCategories] = useState<Set<string>>(new Set());
 64	  const [features, setFeatures] = useState<Set<Feature>>(new Set());
 65	  const [tags, setTags] = useState<Set<string>>(new Set());
 66	  const [owned, setOwned] = useState<"all" | "mine" | "new">("all");
 67	  const [publisher, setPublisher] = useState<string | null>(null);
 68	  /**
 69	   * Which kind of thing is being browsed.
 70	   *
 71	   * Packs first and packs by default, because that is what the
 72	   * marketplace is for and what almost everybody opening it wants. The
 73	   * chooser is not drawn at all until there is a second kind behind it.
 74	   */
 75	  const [kind, setKind] = useState<ListingKind>("pack");
 76	  /**
 77	   * Whether the facets are showing. A wide screen keeps them in the side
 78	   * column and ignores this; a phone has one column, and eleven ways to
 79	   * narrow a list of nineteen packs put the packs two screens below the
 80	   * fold. So they fold behind a word, and the search field, which is what
 81	   * most people reach for first, stays where it is.
 82	   */
 83	  const [filtersOpen, setFiltersOpen] = useState(false);
 84	  const hosted = useHosted();
 85	  const testing = hosted === null || hosted.features.testing;
 86	
 87	  useEffect(() => {
 88	    let live = true;
 89	    void loadMarketplace({ testing }).then((all) => live && setEntries(all));
 90	    return () => {
 91	      live = false;
 92	    };
 93	  }, [testing]);
 94	
 95	  // Arriving on a pack: its docs open once the feed is here, and the search finds it.
 96	  useEffect(() => {
 97	    if (!focus || !entries) return;
 98	    const e = entries.find((x) => x.id === focus);
 99	    if (!e) return;
100	    setQ(e.title);
101	    void showDocs(e);
102	    // Once, on arrival.
103	    // eslint-disable-next-line react-hooks/exhaustive-deps
104	  }, [focus, entries]);
105	
106	  const all = entries ?? [];
107	  const sides = useMemo(() => facets(all), [all]);
108	  const publishers = useMemo(() => publishersOf(all), [all]);
109	  const who = publisher ? (publishers.find((p) => p.id === publisher) ?? null) : null;
110	  const shown = useMemo(
111	    () =>
112	      filterMarketplace(
113	        all,
114	        {
115	          q,
116	          categories,
117	          features,
118	          tags,
119	          kind,
120	          ...(owned === "all" ? {} : { mine: owned === "mine" }),
121	          ...(publisher ? { publisher } : {}),
122	        },
123	        new Set([...mine, ...bought]),
124	      ),
125	    [all, q, categories, features, tags, kind, owned, publisher, mine, bought],
126	  );
127	  const counts = useMemo(() => kindCounts(all), [all]);
128	  /** Drawn only once there is something behind the second tab. */
129	  const kinds: ListingKind[] = counts.setup > 0 ? ["pack", "setup"] : [];
130	  const narrowed = q.trim() !== "" || categories.size > 0 || features.size > 0 || tags.size > 0 || owned !== "all" || publisher !== null;
131	
132	  const toggle = <T,>(set: Set<T>, value: T, put: (next: Set<T>) => void) => {
133	    const next = new Set(set);
134	    if (next.has(value)) next.delete(value);
135	    else next.add(value);
136	    put(next);
137	  };
138	  const clear = () => {
139	    setQ("");
140	    setCategories(new Set());
141	    setFeatures(new Set());
142	    setTags(new Set());
143	    setOwned("all");
144	    setPublisher(null);
145	  };
146	
147	  const showDocs = async (e: MarketplaceEntry) => {
148	    if (reading) return;
149	    setReading(e.id);
150	    try {
151	      // A listing carries its summary ready-made; a priced one has no text to read.
152	      if (e.about) {
153	        const doc = await e.about();
154	        let pack: Pack | null = null;
155	        if (e.price === "free") {
156	          try {
157	            const loaded = loadPackText(await e.load(), "yaml");
158	            pack = loaded.ok ? loaded.pack : null;
159	          } catch {
160	            pack = null;
161	          }
162	        }
163	        if (pack) drawer.open(pack, "summary", { section: "marketplace", id: e.id });
164	        else if (doc) drawer.show(e.title, [{ label: "Summary", what: "The shape of the game, before you have it.", make: () => doc }]);
165	        return;
166	      }
167	      const loaded = loadPackText(await e.load(), "yaml");
168	      if (loaded.ok) drawer.open(loaded.pack, "summary", { section: "marketplace", id: e.id });
169	    } catch {
170	      // Nothing to read: the button simply comes back.
171	    } finally {
172	      setReading(null);
173	    }
174	  };
175	
176	  return (
177	    <main className="main market">
178	      <header className="libraryHead marketHead">
179	        <div>
180	          <h2>Marketplace</h2>
181	          <p className="muted">
182	            Packs anyone may add: the ones that come with the app, and what people have published. Free ones go straight to your packs; a
183	            priced one is bought from its publisher.
184	          </p>
185	        </div>
186	        <button className="ghost tiny" onClick={onBack}>
187	          Back to your packs
188	        </button>
189	      </header>
190	
191	      <div className="marketBody">
192	        <aside className={`marketSide${filtersOpen ? " open" : ""}`} aria-label="Search and filters">
193	          <label className="marketSearch">
194	            <span className="visuallyHidden">Search the marketplace</span>
195	            <input className="textInput" type="search" value={q} placeholder="Search packs…" onChange={(e) => setQ(e.target.value)} />
196	          </label>
197	
198	          {/* The phone's way in and out of the facets; it draws nothing on a wide screen. */}
199	          <button type="button" className="filtersToggle" aria-expanded={filtersOpen} onClick={() => setFiltersOpen((open) => !open)}>
200	            {filtersOpen ? "Hide the filters" : "Filters"}
201	            {narrowed && <span className="chip ok">on</span>}
202	          </button>
203	
204	          {kinds.length > 0 && (
205	            <div className="facet">
206	              <h4 className="facetTitle">Looking for</h4>
207	              <div className="options">
208	                {kinds.map((k) => (
209	                  <button key={k} className={`chip pick ${kind === k ? "on" : ""}`} onClick={() => setKind(k)}>
210	                    {k === "pack" ? "Packs" : "Setups"}
211	                    <span className="muted num">{counts[k]}</span>
212	                  </button>
213	                ))}
214	              </div>
215	              <p className="muted small">
216	                A pack is a game: what the dice can do. A setup is what a tool attached to the game is set to while a run lasts, and fits
217	                any pack for that game.
218	              </p>
219	            </div>
220	          )}
221	
222	          <div className="facet">
223	            <h4 className="facetTitle">Show</h4>
224	            <div className="options">
225	              {(["all", "mine", "new"] as const).map((o) => (
226	                <button key={o} className={`chip pick ${owned === o ? "on" : ""}`} onClick={() => setOwned(o)}>
227	                  {o === "all" ? "Everything" : o === "mine" ? "In your packs" : "Not yet yours"}
228	                </button>
229	              ))}
230	            </div>
231	          </div>
232	
233	          {sides.features.length > 0 && (
234	            <div className="facet">
235	              <h4 className="facetTitle">How it plays</h4>
236	              <ul className="facetList">
237	                {sides.features.map((f) => (
238	                  <li key={f.id}>
239	                    <label title={FEATURES.find((x) => x.id === f.id)?.what}>
240	                      <input type="checkbox" checked={features.has(f.id)} onChange={() => toggle(features, f.id, setFeatures)} />
241	                      <span>{f.value}</span>
242	                      <span className="muted num">{f.count}</span>
243	                    </label>
244	                  </li>
245	                ))}
246	              </ul>
247	            </div>
248	          )}
249	
250	          {sides.categories.length > 0 && (
251	            <div className="facet">
252	              <h4 className="facetTitle">Category</h4>
253	              <ul className="facetList">
254	                {sides.categories.map((c) => (
255	                  <li key={c.value}>
256	                    <label>
257	                      <input
258	                        type="checkbox"
259	                        checked={categories.has(c.value)}
260	                        onChange={() => toggle(categories, c.value, setCategories)}
261	                      />
262	                      <span>{c.value}</span>
263	                      <span className="muted num">{c.count}</span>
264	                    </label>
265	                  </li>
266	                ))}
267	              </ul>
268	            </div>
269	          )}
270	
271	          {publishers.length > 1 && (
272	            <div className="facet">
273	              <h4 className="facetTitle">Publishers</h4>
274	              <ul className="facetList">
275	                {publishers.map((p) => (
276	                  <li key={p.id}>
277	                    <label>
278	                      <input
279	                        type="radio"
280	                        name="publisher"
281	                        checked={publisher === p.id}
282	                        onChange={() => setPublisher(p.id)}
283	                        onClick={() => publisher === p.id && setPublisher(null)}
284	                      />
285	                      <span>{p.name}</span>
286	                      <span className="muted num">{p.count}</span>
287	                    </label>
288	                  </li>
289	                ))}
290	              </ul>
291	            </div>
292	          )}
293	
294	          {sides.tags.length > 0 && (
295	            <div className="facet">
296	              <h4 className="facetTitle">Tags</h4>
297	              <div className="options">
298	                {sides.tags.map((t) => (
299	                  <button
300	                    key={t.value}
301	                    className={`chip pick ${tags.has(t.value) ? "on" : ""}`}
302	                    onClick={() => toggle(tags, t.value, setTags)}
303	                  >
304	                    {t.value}
305	                  </button>
306	                ))}
307	              </div>
308	            </div>
309	          )}
310	
311	          {narrowed && (
312	            <button className="ghost tiny" onClick={clear}>
313	              Clear filters
314	            </button>
315	          )}
316	        </aside>
317	
318	        <section className="marketMain">
319	          {who && (
320	            <section className="panel publisherHead" aria-label="Publisher">
321	              <div>
322	                <span className="muted small mono">Publisher</span>
323	                <h3 className="marketTitle">{who.name}</h3>
324	                <p className="muted small">
325	                  {who.count} {who.count === 1 ? "pack" : "packs"}
326	                  {who.free > 0 && ` · ${who.free} free`}
327	                  {who.from && ` · from ${who.from}`}
328	                </p>
329	              </div>
330	              <button className="ghost tiny" onClick={() => setPublisher(null)}>
331	                All publishers
332	              </button>
333	            </section>
334	          )}
335	          {entries === null && <p className="muted small">Reading the marketplace…</p>}
336	          {entries !== null && (
337	            <p className="muted small marketCount">
338	              {shown.length === all.length ? `${all.length} packs` : `${shown.length} of ${all.length} packs`}
339	            </p>
340	          )}
341	          {entries !== null && shown.length === 0 && <p className="muted">Nothing matches. Loosen a filter, or clear them.</p>}
342	          <div className="marketGrid">
343	            {shown.map((e) => {
344	              const have = mine.has(e.id);
345	              return (
346	                <article key={e.id} className="panel marketCard">
347	                  <header className="marketCardHead">
348	                    <span className="pill">{e.category}</span>
349	                    <span className={`muted small ${e.price !== "free" ? "priceTag" : ""}`}>
350	                      {e.price === "free" ? "free" : e.price.display}
351	                    </span>
352	                  </header>
353	                  <h3 className="marketTitle">
354	                    {e.title}
355	                    {e.bench && <span className="chip cap">test bench</span>}
356	                  </h3>
357	                  <p className="muted small">
358	                    {e.author && `by ${e.author} · `}v{e.version}
359	                    {e.players > 1 && ` · up to ${e.players} people`}
360	                    {e.publisher && e.publisher.name !== e.author && (
361	                      <>
362	                        {" · "}
363	                        <button
364	                          className="publisherLink"
365	                          onClick={() => setPublisher(e.publisher!.id)}
366	                          title={`Everything ${e.publisher.name} has listed`}
367	                        >
368	                          {e.publisher.name}
369	                        </button>
370	                      </>
371	                    )}
372	                  </p>
373	                  {e.description && <p className="marketBlurb clamp">{e.description}</p>}
374	                  {e.requires.length > 0 && (
375	                    <p className="muted small marketNeeds">
376	                      {e.requires.some((r) => !r.optional) && (
377	                        <>
378	                          <strong>Needs:</strong>{" "}
379	                          {e.requires
380	                            .filter((r) => !r.optional)
381	                            .map((r) => r.label)
382	                            .join("; ")}
383	                          .{" "}
384	                        </>
385	                      )}
386	                      {e.requires.some((r) => r.optional) && (
387	                        <>
388	                          <strong>Better with:</strong>{" "}
389	                          {e.requires
390	                            .filter((r) => r.optional)
391	                            .map((r) => r.label)
392	                            .join("; ")}
393	                          .
394	                        </>
395	                      )}
396	                    </p>
397	                  )}
398	                  <div className="entryTags">
399	                    {e.features.map((f) => (
400	                      <span key={f} className="chip cap" title={FEATURES.find((x) => x.id === f)?.what}>
401	                        {FEATURES.find((x) => x.id === f)?.label ?? f}
402	                      </span>
403	                    ))}
404	                  </div>
405	                  {e.tags.length > 0 && (
406	                    <div className="entryTags">
407	                      {e.tags.map((t) => (
408	                        <button
409	                          key={t}
410	                          className={`chip pick ${tags.has(t) ? "on" : ""}`}
411	                          title="Filter by this tag"
412	                          onClick={() => toggle(tags, t, setTags)}
413	                        >
414	                          {t}
415	                        </button>
416	                      ))}
417	                    </div>
418	                  )}
419	                  <footer className="marketCardFoot">
420	                    <div className="marketCardFootLeft">
421	                      <button
422	                        className="ghost tiny"
423	                        disabled={reading === e.id}
424	                        title="The summary, and the rest of the pack's paper, in the side drawer"
425	                        onClick={() => void showDocs(e)}
426	                      >
427	                        {reading === e.id ? "Reading…" : "Docs"}
428	                      </button>
429	                      {have && <span className="chip cap">In your packs</span>}
430	                    </div>
431	                    {have ? (
432	                      <button className="ghost tiny" onClick={() => onOpen(e.id)}>
433	                        Open
434	                      </button>
435	                    ) : bought.has(e.id) && onFetch ? (
436	                      <button
437	                        className="primary tiny"
438	                        disabled={busy === e.id}
439	                        title="You bought this; fetch your copy onto this device"
440	                        onClick={() => {
441	                          setBusy(e.id);
442	                          void onFetch(e).finally(() => setBusy(null));
443	                        }}
444	                      >
445	                        {busy === e.id ? "Fetching…" : "Yours · get your copy"}
446	                      </button>
447	                    ) : e.price !== "free" ? (
448	                      <button
449	                        className="primary tiny"
450	                        disabled={busy === e.id || !onBuy}
451	                        title={onBuy ? `Buy from ${e.publisher?.name ?? "its publisher"}` : "Sign in to buy"}
452	                        onClick={() => {
453	                          if (!onBuy) return;
454	                          setBusy(e.id);
455	                          void onBuy(e).finally(() => setBusy(null));
456	                        }}
457	                      >
458	                        {busy === e.id ? "Opening…" : `Buy · ${e.price.display}`}
459	                      </button>
460	                    ) : (
461	                      <button
462	                        className="primary tiny"
463	                        disabled={busy === e.id}
464	                        onClick={() => {
465	                          setBusy(e.id);
466	                          void onAdd(e).finally(() => setBusy(null));
467	                        }}
468	                      >
469	                        {busy === e.id ? "Adding…" : "Add to my packs"}
470	                      </button>
471	                    )}
472	                  </footer>
473	                </article>
474	              );
475	            })}
476	          </div>
477	        </section>
478	      </div>
479	    </main>
480	  );
481	}

