    const parts = path.split("/").slice(0, -1);
    for (let i = 1; i <= parts.length; i++) folders.add(parts.slice(0, i).join("/"));
  }
  for (const dir of [...folders].sort()) entries.push({ name: `${folder}/${dir}/` });
