  const [nothing, setNothing] = useState(false);
  const [busy, setBusy] = useState<DeviceId | null>(null);
  useDismiss(root, open, () => setOpen(false));

  if (nothing) return null;

  const read = async () => {
    if (pack) return;
    try {
      const parsed = loadPackText(await load(), "yaml");
