/* A row's own small menu: unlist, remove, folded away so a listing reads as its price, not a control panel. */
.rowMenu {
  position: relative;
}
.rowMenu > summary,
.rowMenuBtn {
  list-style: none;
  cursor: pointer;
  padding: 0.15rem 0.55rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--muted);
  font-size: 0.85rem;
}
.rowMenu > summary::-webkit-details-marker {
  display: none;
}
@media (hover: hover) {
  .rowMenu > summary:hover {
    border-color: var(--line-2);
    color: var(--text);
  }
}
.rowMenuPanel {
  position: absolute;
  right: 0;
  top: calc(100% + 0.3rem);
  z-index: 5;
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  min-width: 8rem;
  padding: 0.3rem;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--raise);
}
.rowMenuPanel button {
  text-align: left;
  padding: 0.3rem 0.5rem;
  border: none;
  background: transparent;
  color: inherit;
  font: inherit;
  border-radius: 6px;
  cursor: pointer;
}
@media (hover: hover) {
  .rowMenuPanel button:hover {
    background: var(--panel-2);
  }
}

