// @vitest-environment jsdom
import { afterEach, describe, expect, it, vi } from "vitest";
import { cleanup, fireEvent, render, screen, waitFor } from "@testing-library/react";
import demo from "../../../../packs/demo/pack.yaml?raw";
import { DeckProfiles } from "./DeckProfiles.tsx";

/**
 * The download a pack's own page offers.
 *
 * What is actually built is held to the shipped profiles in
 * `packages/deck-profiles`, byte for byte. What is checked here is the
 * other half: that the row asks for the pack only when somebody opens it,
 * that a pack with nothing of its own to lay out draws no row at all, and
 * that pressing a deck gets as far as handing the browser a file. jsdom has
 * no `URL.createObjectURL`, so it is stood in for; without it the press
 * would throw and the test would be about jsdom rather than about this.
 */

afterEach(cleanup);

/** The demo pack with its moves, counters and resources taken out. */
const bare = demo.replace(/^(counters|resources|moves):[\s\S]*?(?=\n[a-z]+:)/gm, "");

const objectUrls = () => {
  const made: string[] = [];
  const url = URL as unknown as { createObjectURL: (b: Blob) => string; revokeObjectURL: (u: string) => void };
  url.createObjectURL = (blob: Blob) => {
    made.push(blob.type);
    return "blob:deck";
  };
  url.revokeObjectURL = () => {};
  return made;
};

describe("a Stream Deck profile from a pack's page", () => {
  it("does not read the pack until somebody opens the row", async () => {
    const load = vi.fn(async () => demo);
    render(<DeckProfiles load={load} />);
    expect(load).not.toHaveBeenCalled();
    fireEvent.click(screen.getByText("Stream Deck profile"));
    await waitFor(() => expect(load).toHaveBeenCalledTimes(1));
  });

  it("offers one download per deck", async () => {
    render(<DeckProfiles load={async () => demo} />);
    fireEvent.click(screen.getByText("Stream Deck profile"));
    await waitFor(() => expect(screen.getByRole("button", { name: "XL" })).toBeTruthy());
    expect(["XL", "Stream Deck", "Mini", "+"].map((label) => screen.getByRole("button", { name: label }).textContent)).toEqual([
      "XL",
      "Stream Deck",
      "Mini",
      "+",
    ]);
  });

  it("builds the file and hands it to the browser", async () => {
    const made = objectUrls();
    const clicks: string[] = [];
    const anchor = document.createElement("a");
    vi.spyOn(document, "createElement").mockImplementation((tag: string) => {
      if (tag !== "a") return Object.getPrototypeOf(document).createElement.call(document, tag) as HTMLElement;
      anchor.click = () => clicks.push(anchor.download);
      return anchor;
    });
    try {
      render(<DeckProfiles load={async () => demo} />);
      fireEvent.click(screen.getByText("Stream Deck profile"));
      await waitFor(() => expect(screen.getByRole("button", { name: "Mini" })).toBeTruthy());
      fireEvent.click(screen.getByRole("button", { name: "Mini" }));
      await waitFor(() => expect(clicks).toEqual(["com.scrthq.runlog.long-kiln-mini.streamDeckProfile"]));
      expect(made).toEqual(["application/zip"]);
    } finally {
      vi.restoreAllMocks();
    }
  });

  it("draws nothing for a pack with no moves, counters or resources", async () => {
    const { container } = render(<DeckProfiles load={async () => bare} />);
    fireEvent.click(screen.getByText("Stream Deck profile"));
    await waitFor(() => expect(container.innerHTML).toBe(""));
  });
});

